$ErrorActionPreference='Stop'; $html=Get-Content (Join-Path $PSScriptRoot 'DETAILED_PROJECT_STUDY_GUIDE.html') -Raw; $body=[regex]::Match($html,'<body>(.*?)</body>','Singleline').Groups[1].Value; $plain=[regex]::Replace($body,'<(br|p|li|h[1-3]|tr|div)[^>]*>',"`n"); $plain=[regex]::Replace($plain,'<[^>]+>',''); $plain=[System.Net.WebUtility]::HtmlDecode($plain); $lines=$plain -split "`n" | ForEach-Object {$_.Trim()} | Where-Object {$_}; $esc={param($s)[System.Security.SecurityElement]::Escape($s)}; $paras=foreach($line in $lines){"<w:p><w:r><w:t xml:space=`"preserve`">$(&$esc $line)</w:t></w:r></w:p>"}; $document='<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:document xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:body>'+($paras -join '')+'<w:sectPr><w:pgSz w:w="12240" w:h="15840"/><w:pgMar w:top="900" w:right="900" w:bottom="900" w:left="900"/></w:sectPr></w:body></w:document>'; $root=Join-Path $env:TEMP ('sms-detailed-docx-'+[guid]::NewGuid()); New-Item -ItemType Directory -Path (Join-Path $root '_rels') -Force|Out-Null; New-Item -ItemType Directory -Path (Join-Path $root 'word\_rels') -Force|Out-Null; Set-Content -LiteralPath (Join-Path $root '[Content_Types].xml') '<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/></Types>'; Set-Content (Join-Path $root '_rels\.rels') '<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/></Relationships>'; Set-Content (Join-Path $root 'word\document.xml') $document; $out=Join-Path $PSScriptRoot 'Student-Management-System-Deep-Study-Guide.docx'; if(Test-Path $out){Remove-Item $out}; Add-Type -AssemblyName System.IO.Compression.FileSystem; [System.IO.Compression.ZipFile]::CreateFromDirectory($root,$out); Remove-Item $root -Recurse -Force
